    for ri,(a,b) in enumerate(Rb):
        for ci,(c,d) in enumerate(Cb):
            P=[(i-a,j-c,g[i][j]) for i in range(a,b+1) for j in range(c,d+1)]
            vals=Counter(v for _,_,v in P)
            nz={v:n for v,n in vals.items() if v!=sep}
