def f(g, dbg=False):
    H=len(g); W=len(g[0])
    cnt=Counter(v for r in g for v in r)
    sep=None
    for c in cnt:
        fullrow=any(all(v==c for v in g[i]) for i in range(H))
        if fullrow:
            fullcol=any(all(g[i][j]==c for i in range(H)) for j in range(W))
            if fullcol: sep=c
    sr=[i for i in range(H) if all(v==sep for v in g[i])]
    sc=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    Rb=bands(sr,H); Cb=bands(sc,W)
    T={}
    for ri,(a,b) in enumerate(Rb):
        for ci,(c,d) in enumerate(Cb):
            P=[(i-a,j-c,g[i][j]) for i in range(a,b+1) for j in range(c,d+1)]
            vals=Counter(v for _,_,v in P)
            bg=vals.most_common(1)[0][0]
            keep=[(i,j,v) for i,j,v in P if v!=bg]
            rs=[p[0] for p in keep]; cs=[p[1] for p in keep]
            if keep:
                T[(ri,ci)]=tuple(sorted((i-min(rs),j-min(cs),v) for i,j,v in keep))
            else:
