                if (hq,wq)!=(hgt,wid): continue
                hits.append((lab,q))
        if len(hits)!=1:
            if dbg: print('tile',kt,'hits:',hits)
            continue
        sk,q=hits[0]
        for i,j,v in q: out[ta+i][tca+j]=v
    return out,T

